  "home.atelier": {"el": "Το ίδιο ράφι, σε άλλες γλώσσες", "de": "Dasselbe Regal, andere Sprachen", "fr": "Même étagère, autres langues", "it": "Lo stesso scaffale, altre lingue", "es": "El mismo estante, en otros idiomas", "nl": "Dezelfde plank, in andere talen", "pl": "Ta sama półka, w innych językach", "no": "Samme hylle, andre språk", "bg": "Същият рафт, на други езици", "ro": "Același raft, în alte limbi", "sv": "Samma hylla, andra språk", "da": "Samme hylde, andre sprog", "fi": "Sama hylly, eri kieliä", "pt": "A mesma prateleira, noutras línguas", "hu": "Ugyanaz a polc, más nyelveken", "cs": "Stejná police, jiné jazyky", "hr": "Ista polica, drugi jezici", "sk": "Rovnaká polica, iné jazyky"},
  "home.atelierLead": {"el": "Ο ιστότοπος διαβάζεται σε 12 γλώσσες· το ράφι παραμένει το ίδιο.", "de": "Die Seite ist in 12 Sprachen lesbar; das Regal bleibt dasselbe.", "fr": "Le site se lit en 12 langues ; l’étagère reste la même.", "it": "Il sito si legge in 12 lingue; lo scaffale è lo stesso.", "es": "La web se lee en 12 idiomas; el estante sigue siendo el mismo.", "nl": "De site is te lezen in 12 talen; de plank blijft dezelfde.", "pl": "Stronę można czytać w 12 językach; półka pozostaje ta sama.", "no": "Nettstedet kan leses på 12 språk; hyllen er den samme.", "bg": "Сайтът се чете на 12 езика; рафтът е същият.", "ro": "Site-ul se citește în 12 limbi; raftul rămâne același.", "sv": "Webbplatsen kan läsas på 12 språk; hyllan är densamma.", "da": "Siden kan læses på 12 sprog; hylden er den samme.", "fi": "Sivusto on luettavissa 12 kielellä; hylly on aina sama.", "pt": "O site pode ser lido em 12 línguas; a prateleira é a mesma.", "hu": "Az oldal 12 nyelven olvasható; a polc ugyanaz a polc.", "cs": "Stránky si můžete číst ve 12 jazycích; police zůstává tatáž.", "hr": "Stranica se čita na 12 jezika; polica ostaje ista.", "sk": "Stránka sa číta v 12 jazykoch; polica zostáva tá istá."},
