  "ship.l5": {"el": "Έχετε δικαίωμα επιστροφής εντός 14 ημερών από την παράδοση.", "de": "Sie haben nach der Zustellung 14 Tage Rückgaberecht.", "fr": "Vous disposez de 14 jours après réception pour exercer votre retour.", "it": "Hai 14 giorni di tempo dalla consegna per restituire i prodotti.", "es": "Tienes derecho a devolución dentro de los 14 días posteriores a la entrega.", "nl": "Je hebt 14 dagen na levering het recht om te retourneren.", "pl": "Masz prawo do zwrotu w ciągu 14 dni od otrzymania przesyłki.", "no": "Du har 14 dagers angrerett etter levering.", "bg": "Имате право на връщане в рамките на 14 дни след доставката.", "ro": "Aveți drept de retur în termen de 14 zile de la livrare.", "sv": "Du har 14 dagars ångerrätt efter leverans.", "da": "Du har 14 dages fortrydelsesret efter modtagelse.", "fi": "Sinulla on 14 päivän palautusoikeus toimituksen jälkeen.", "pt": "Tem 14 dias após a entrega para exercer o direito de devolução.", "hu": "A kézbesítést követő 14 napon belül elállási joga van.", "cs": "Na vrácení zboží máte 14 dní od převzetí zásilky.", "hr": "Imate pravo na povrat u roku od 14 dana od dostave.", "sk": "Máte právo na vrátenie tovaru do 14 dní od doručenia."},
  "eta.gr": {"el": "Εντός Ελλάδας, λίγες εργάσιμες ημέρες", "de": "Innerhalb Griechenlands, wenige Werktage", "fr": "En Grèce, quelques jours ouvrés", "it": "In Grecia, pochi giorni lavorativi", "es": "En Grecia, pocos días laborables", "nl": "Binnen Griekenland, enkele werkdagen", "pl": "W Grecji, kilka dni roboczych", "no": "Innen Hellas, noen få virkedager", "bg": "В рамките на Гърция, няколко работни дни", "ro": "În Grecia, câteva zile lucrătoare", "sv": "Inom Grekland, några arbetsdagar", "da": "Inden for Grækenland, et par hverdage", "fi": "Kreikan sisällä, muutama arkipäivä", "pt": "Grécia: alguns dias úteis", "hu": "Görögországon belül, néhány munkanap", "cs": "Po Řecku, několik pracovních dnů", "hr": "Unutar Grčke, nekoliko radnih dana", "sk": "V rámci Grécka, niekoľko pracovných dní"},
