  "uyum.need": {"el": "Επίσης: επωνυμία, ΑΦΜ, ΓΕΜΗ, πλήρης διεύθυνση, τηλέφωνο, email.", "de": "Außerdem: offizieller Name, ΑΦΜ, GEMI, vollständige Adresse, Telefon, E-Mail.", "fr": "Également : raison sociale, ΑΦΜ, GEMI, adresse complète, téléphone, e-mail.", "it": "Inoltre: ragione sociale, ΑΦΜ, GEMI, indirizzo completo, telefono, e-mail.", "es": "También: razón social, ΑΦΜ, GEMI, dirección completa, teléfono, correo electrónico.", "nl": "Ook: officiële bedrijfsnaam, ΑΦΜ, GEMI, volledig adres, telefoon, e-mail.", "pl": "Ponadto: nazwa prawna, ΑΦΜ, GEMI, pełny adres, telefon, e-mail.", "no": "Også: juridisk navn, mva-nummer (ΑΦΜ), GEMI, fullstendig adresse, telefon, e-post.", "bg": "Също така: юридическо име, ДДС номер (ΑΦΜ), GEMI, пълен адрес, телефон, имейл.", "ro": "De asemenea: denumire legală, CIF (ΑΦΜ), GEMI, adresă completă, telefon, e-mail.", "sv": "Dessutom: juridiskt namn, momsnummer, GEMI, fullständig adress, telefon, e-post.", "da": "Desuden: juridisk navn, momsnr., GEMI, fuld adresse, telefon, e-mail.", "fi": "Lisäksi: virallinen toiminimi, ALV-numero, GEMI, täydellinen osoite, puhelin, sähköposti.", "pt": "Também: denominação social, NIF (ΑΦΜ), GEMI, morada completa, telefone, e-mail.", "hu": "Továbbá: cégnév, adószám (ΑΦΜ), GEMI, pontos cím, telefon, e-mail.", "cs": "Dále: obchodní firma, DIČ (ΑΦΜ), GEMI, úplná adresa, telefon, e-mail.", "hr": "Također: pravni naziv, porezni broj (ΑΦΜ), GEMI, puna adresa, telefon, e-pošta.", "sk": "Tiež: obchodné meno, DIČ/IČ DPH (ΑΦΜ), GEMI, úplná adresa, telefón, e-mail."},
  "seo.home.title": {"el": "Detoks.gr | Φροντίδα ριζωμένη στη Ροδόπη", "de": "Detoks.gr | In den Rhodopen verwurzelte Sorgfalt", "fr": "Detoks.gr | Une attention enracinée dans les Rhodopes", "it": "Detoks.gr | Cura radicata nei Rodopi", "es": "Detoks.gr | Cuidado arraigado en Ródope", "nl": "Detoks.gr | Zorg geworteld in de Rodopen", "pl": "Detoks.gr | Troska zakorzeniona w Rodopach", "no": "Detoks.gr | Omsorg med røtter i Rhodopene", "bg": "Detoks.gr | Грижа с корени в Родопите", "ro": "Detoks.gr | Grijă cu rădăcini în Rodopi", "sv": "Detoks.gr | Omsorg med rötter i Rhodopebergen", "da": "Detoks.gr | Omsorg med rødder i Rhodopebjergene", "fi": "Detoks.gr | Rodopeille juurtunutta huolenpitoa", "pt": "Detoks.gr | Cuidado com raízes no Ródope", "hu": "Detoks.gr | A Rodope vidékén gyökerező gondoskodás", "cs": "Detoks.gr | Péče zakořeněná v Rodopech", "hr": "Detoks.gr | Pažnja ukorijenjena u Rodopima", "sk": "Detoks.gr | Starostlivosť zakorenená v Rodopoch"},
  "seo.home.desc": {"el": "Το βοτανοπωλείο του Taha Hüseyinoğlu στην Κομοτηνή. Όσα ετοιμάζει ο ίδιος και όσα επιλέγει· το δέμα φεύγει από τη Ροδόπη.", "de": "Taha Hüseyinoğlus Kräuterladen in Komotini. Was er selbst zubereitet und was er auswählt; die Pakete kommen aus den Rhodopen.", "fr": "L’herboristerie de Taha Hüseyinoğlu à Komotini. Ce qu’il prépare et ce qu’il choisit ; les colis partent des Rhodopes.", "it": "L’erboristeria di Taha Hüseyinoğlu a Komotini. Quello che prepara e quello che sceglie; i pacchi partono dai Rodopi.", "es": "El herbolario de Taha Hüseyinoğlu en Komotini. Lo que él prepara y lo que él selecciona; el paquete sale de Ródope.", "nl": "De kruidenwinkel van Taha Hüseyinoğlu in Komotini. Wat hij zelf bereidt en wat hij selecteert; het pakket vertrekt uit de Rodopen.", "pl": "Zielarnia Tahy Hüseyinoğlu w Komotini. To, co sam przygotowuje, i to, co wybiera; paczka wyrusza z Rodopów.", "no": "Taha Hüseyinoğlus urtebutikk i Komotini. Det han lager selv og det han velger ut; pakken sendes fra Rhodopene.", "bg": "Билковият дюкян на Таха Хюсеиноглу в Комотини. Това, което приготвя сам, и това, което подбира; пратката тръгва от Родопите.", "ro": "Prăvălia de plante a lui Taha Hüseyinoğlu din Komotini. Ce pregătește el însuși și ce alege; coletul pleacă din Rodopi.", "sv": "Taha Hüseyinoğlus örtbutik i Komotini. Det han tillreder själv och det han väljer ut; paketet skickas från Rhodopebergen.", "da": "Taha Hüseyinoğlus urtebutik i Komotini. Det han selv tilbereder, og det han udvælger; pakken sendes fra Rhodopebjergene.", "fi": "Taha Hüseyinoğlun yrttipuoti Komotinissa. Hänen valmistamansa ja valikoimansa tuotteet; paketti lähetetään Rodopeilta.", "pt": "A ervanária de Taha Hüseyinoğlu em Komotini. O que ele prepara e o que seleciona; a encomenda parte do Ródope.", "hu": "Taha Hüseyinoğlu komotini fűszer- és gyógynövényboltja. Saját készítésű és gondosan válogatott termékek; a csomag a Rodope vidékéről indul.", "cs": "Bylinářství Tahy Hüseyinoğlua v Komotini. Co sám připravuje i co vybírá; balíček odchází z Rodop.", "hr": "Biljna trgovina Tahe Hüseyinoğlua u Komotiniju. Ono što sam priprema i ono što bira; paket kreće iz Rodopa.", "sk": "Bylinkárstvo Tahu Hüseyinoğlua v Komotini. Čo sám pripravuje a čo vyberá; balík odchádza z Rodopov."},
